using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
// In .NET 9+ you can also use the generic extension if available;
// the cast above always works and gives you the typed metadata.

Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"Sample serialize: {JsonSerializer.Serialize(new Person("Alice", 30), personInfo)}");

// 2) Probe without throwing: TryGetTypeInfo returns false if metadata isn't available
//    Here we use a resolver that only knows about Person, not about UnknownRecord.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new PersonOnlyResolver()
};

if (limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
    Console.WriteLine($"\nPerson metadata found via TryGetTypeInfo: {found!.Type.Name}");

if (!limited.TryGetTypeInfo(typeof(UnknownRecord), out _))
    Console.WriteLine("UnknownRecord metadata NOT available (no exception thrown).");

// --- Types ---

record Person(string Name, int Age);
record UnknownRecord(string Data);

// A custom resolver that only resolves Person
sealed class PersonOnlyResolver : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(Person))
            return _inner.GetTypeInfo(type, options);
        return null; // signal "not available"
    }
}

